begin;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select plan(15);
insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data)values('1c000000-0000-4000-8000-000000000001','plan-owner@example.test','{}','{}'),('1c000000-0000-4000-8000-000000000002','plan-accountant@example.test','{}','{}');insert into public.workspaces(id,name,owner_id)values('2c000000-0000-4000-8000-000000000001','Forecast Workspace','1c000000-0000-4000-8000-000000000001');insert into public.workspace_members(workspace_id,user_id,role)values('2c000000-0000-4000-8000-000000000001','1c000000-0000-4000-8000-000000000002','accountant');insert into public.categories(id,workspace_id,name,kind,created_by)values('3c000000-0000-4000-8000-000000000001','2c000000-0000-4000-8000-000000000001','Marketing','expense','1c000000-0000-4000-8000-000000000001');
set local role authenticated;select throws_ok($$select public.mutate_financial_plan('2c000000-0000-4000-8000-000000000001','1c000000-0000-4000-8000-000000000001','plan-denied-0001','goal',null,null,'x','{}')$$,'42501',null,'authenticated clients cannot call the service function');reset role;
create temporary table goal_create as select public.mutate_financial_plan('2c000000-0000-4000-8000-000000000001','1c000000-0000-4000-8000-000000000001','goal-create-0001','goal',null,null,'goal-hash','{"year":2026,"gciTarget":"150000.00","netIncomeTarget":"100000.00","closedTransactionsTarget":20,"taxReserveTarget":"30000.00","marketingBudget":"12000.00","targetExpenseRatioPct":25,"deviceId":"database-test"}')result;
select is((select result->>'version'from goal_create),'1','goal begins at version one');select is((select gci_target::text from public.goals where id=(select(result->>'id')::uuid from goal_create)),'150000.00','GCI target is exact');select is((select count(*)::integer from public.audit_events where request_id='goal-create-0001'),1,'goal writes an audit event');select is((select count(*)::integer from public.sync_operations where client_mutation_id='goal-create-0001'),1,'goal writes a sync receipt');select is(public.mutate_financial_plan('2c000000-0000-4000-8000-000000000001','1c000000-0000-4000-8000-000000000001','goal-create-0001','goal',null,null,'goal-hash','{}')->>'id',(select result->>'id'from goal_create),'goal retry is idempotent');
create temporary table goal_update as select public.mutate_financial_plan('2c000000-0000-4000-8000-000000000001','1c000000-0000-4000-8000-000000000001','goal-update-0001','goal',(select(result->>'id')::uuid from goal_create),1,'goal-update','{"year":2026,"gciTarget":"175000.00","netIncomeTarget":"110000.00","closedTransactionsTarget":22,"taxReserveTarget":"32000.00","marketingBudget":"14000.00","targetExpenseRatioPct":24,"deviceId":"database-test"}')result;select is((select result->>'version'from goal_update),'2','goal update increments version');select throws_ok(format($$select public.mutate_financial_plan('2c000000-0000-4000-8000-000000000001','1c000000-0000-4000-8000-000000000001','goal-stale-0001','goal',%L,1,'stale','{"year":2026}')$$,(select result->>'id'from goal_create)),'40001','Record version conflict','stale goal updates are rejected');
create temporary table budget_create as select public.mutate_financial_plan('2c000000-0000-4000-8000-000000000001','1c000000-0000-4000-8000-000000000001','budget-create-0001','budget',null,null,'budget-hash','{"year":2026,"name":"Operating budget","deviceId":"database-test","lines":[{"categoryId":"3c000000-0000-4000-8000-000000000001","month":1,"amount":"1500.25"},{"categoryId":null,"month":1,"amount":"500.00"}]}')result;
select is((select result->>'version'from budget_create),'1','budget begins at version one');select is((select count(*)::integer from public.budget_lines where budget_id=(select(result->>'id')::uuid from budget_create)),2,'budget stores all monthly lines');select is((select sum(amount)::numeric(14,2)::text from public.budget_lines where budget_id=(select(result->>'id')::uuid from budget_create)),'2000.25','budget lines preserve exact cents');select is((select count(*)::integer from public.audit_events where request_id='budget-create-0001'),1,'budget writes an audit event');select is((select count(*)::integer from public.sync_operations where client_mutation_id='budget-create-0001'),1,'budget writes a sync receipt');
select throws_ok($$select public.mutate_financial_plan('2c000000-0000-4000-8000-000000000001','1c000000-0000-4000-8000-000000000002','accountant-plan-0001','goal',null,null,'x','{"year":2027}')$$,'P0001','Not authorized to change financial plans','accountants remain read-only');select throws_ok($$select public.mutate_financial_plan('2c000000-0000-4000-8000-000000000001','1c000000-0000-4000-8000-000000000001','bad-category-0001','budget',null,null,'x','{"year":2027,"name":"Bad budget","lines":[{"categoryId":"3c000000-0000-4000-8000-000000000099","month":1,"amount":"10.00"}]}')$$,'P0001','Budget category is not available in this workspace','unknown budget categories are rejected');select * from finish();rollback;
